const token = $env.PAPERLESS_API_TOKEN;
const calendarUrl = String($env.PAPERLESS_CALENDAR_URL ?? '').replace(/\/+$/, '') + '/';
if (!token) throw new Error('PAPERLESS_API_TOKEN is not configured');
if (!/^https:\/\//.test(calendarUrl)) throw new Error('PAPERLESS_CALENDAR_URL is not configured');
const headers = {Authorization: `Token ${token}`};
const api = async (method, path, body) =>
  await this.helpers.httpRequest({method, url: `http://127.0.0.1:8445${path}`, headers, body, json: true});

const fieldsResponse = await api('GET', '/api/custom_fields/?page_size=100');
let field = fieldsResponse.results.find((candidate) => candidate.name === 'Calendar date');
if (!field) field = await api('POST', '/api/custom_fields/', {name: 'Calendar date', data_type: 'date'});

const documents = [];
let next = `/api/documents/?page_size=100&custom_fields__id__in=${field.id}`;
while (next) {
  const pagePath = next.replace(/^https?:\/\/[^/]+/, '');
  const page = await api('GET', pagePath);
  documents.push(...page.results);
  next = page.next;
}

const escapeIcs = (value) => String(value ?? '').replace(/\\/g, '\\\\').replace(/\r?\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
const hash = (value) => {
  let result = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) result = Math.imul(result ^ value.charCodeAt(i), 0x01000193);
  return (result >>> 0).toString(16).padStart(8, '0');
};
const addDay = (date) => {
  const value = new Date(`${date}T12:00:00Z`);
  value.setUTCDate(value.getUTCDate() + 1);
  return value.toISOString().slice(0, 10);
};
const compact = (date) => date.replaceAll('-', '');

const desired = {};
for (const document of documents) {
  const value = document.custom_fields?.find((entry) => entry.field === field.id)?.value;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value ?? ''))) continue;
  const href = `paperless-document-${document.id}.ics`;
  const body = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//n8n//Paperless dates//EN',
    'CALSCALE:GREGORIAN',
    'BEGIN:VEVENT',
    `UID:paperless-${document.id}@n8n.local`,
    `DTSTART;VALUE=DATE:${compact(value)}`,
    `DTEND;VALUE=DATE:${compact(addDay(value))}`,
    // Keep the generated file stable across retries. Using the current time
    // here would change the hash and rewrite every event on every run.
    `DTSTAMP:${compact(value)}T000000Z`,
    `SUMMARY:${escapeIcs(document.title)}`,
    `DESCRIPTION:${escapeIcs(`Paperless document #${document.id}\\nhttps://paperless.hugo-berendi.de/documents/${document.id}/details`)}`,
    'TRANSP:TRANSPARENT',
    'END:VEVENT',
    'END:VCALENDAR',
    '',
  ].join('\r\n');
  desired[href] = {hash: hash(body), body};
}

const state = $getWorkflowStaticData('global');
state.calendar ??= {};
const operations = [];
for (const [href, event] of Object.entries(desired)) {
  if (state.calendar[href] !== event.hash) {
    operations.push({method: 'PUT', href, url: calendarUrl + href, body: event.body, hash: event.hash});
  }
}
for (const href of Object.keys(state.calendar)) {
  if (!(href in desired)) operations.push({method: 'DELETE', href, url: calendarUrl + href, body: ''});
}
if (!operations.length) return [];
return operations.map((operation) => ({json: operation}));

const op = $('Prepare document calendar').item.json;
const state = $getWorkflowStaticData('global');
state.calendar ??= {};
if (op.method === 'PUT') state.calendar[op.href] = op.hash;
else delete state.calendar[op.href];
return $input.item;

const token = $env.PAPERLESS_API_TOKEN;
if (!token) throw new Error('PAPERLESS_API_TOKEN is not configured');
const headers = {Authorization: `Token ${token}`};
const api = async (method, path, body) =>
  await this.helpers.httpRequest({method, url: `http://127.0.0.1:8445${path}`, headers, body, json: true});

const fieldsResponse = await api('GET', '/api/custom_fields/?page_size=100');
let field = fieldsResponse.results.find((candidate) => candidate.name === 'Reminder date');
if (!field) field = await api('POST', '/api/custom_fields/', {name: 'Reminder date', data_type: 'date'});

const documents = [];
let next = `/api/documents/?page_size=100&custom_fields__id__in=${field.id}`;
while (next) {
  const pagePath = next.replace(/^https?:\/\/[^/]+/, '');
  const page = await api('GET', pagePath);
  documents.push(...page.results);
  next = page.next;
}

const today = new Date();
today.setHours(12, 0, 0, 0);
const wantedDays = new Set([30, 14, 7, 3, 1, 0]);
const due = [];
for (const document of documents) {
  const date = document.custom_fields?.find((entry) => entry.field === field.id)?.value;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date ?? ''))) continue;
  const target = new Date(`${date}T12:00:00`);
  const days = Math.round((target - today) / 86400000);
  if (wantedDays.has(days)) due.push({id: document.id, title: document.title, date, days});
}
if (!due.length) return [];

const state = $getWorkflowStaticData('global');
state.sent ??= {};
const unsent = due.filter((item) => !state.sent[`${item.id}:${item.date}:${item.days}`]);
if (!unsent.length) return [];
const keys = unsent.map((item) => `${item.id}:${item.date}:${item.days}`);
const esc = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
const rows = unsent
  .map((item) => `<tr><td style="padding:10px 0;border-bottom:1px solid #393552;color:#e0def4;"><a href="https://paperless.hugo-berendi.de/documents/${item.id}/details" style="color:#9ccfd8;font-weight:bold;">${esc(item.title)}</a><br><span style="color:#f6c177;">${esc(item.date)} · ${item.days === 0 ? 'today' : `${item.days} days`}</span></td></tr>`)
  .join('');
const html = `<html><body style="margin:0;padding:24px;background:#232136;"><table role="presentation" width="100%" style="max-width:600px;margin:auto;background:#2a273f;border:1px solid #393552;padding:24px;font-family:Verdana,sans-serif;"><tr><td style="color:#c4a7e7;font:700 20px 'Courier New',monospace;">PAPERLESS REMINDERS</td></tr>${rows}</table></body></html>`;
return [{json: {subject: `[Paperless] ${unsent.length} document reminder${unsent.length === 1 ? '' : 's'}`, html, sentKeys: keys, unsent}}];

const keys = $('Prepare reminders').first().json.sentKeys;
const state = $getWorkflowStaticData('global');
state.sent ??= {};
const now = Date.now();
for (const key of keys) state.sent[key] = now;
for (const [key, timestamp] of Object.entries(state.sent)) {
  if (now - Number(timestamp) > 180 * 86400000) delete state.sent[key];
}
return $input.all();

// The reminder mail covers the whole ladder -- 30, 14, 7, 3, 1 and 0 days. Only
// the last three reach the phone: a month of notice is a thing to read, three
// days is a thing to act on.
const PUSH_WITHIN_DAYS = 3;
const { unsent = [] } = $input.first().json;

const soon = unsent.filter((item) => item.days <= PUSH_WITHIN_DAYS);
if (soon.length === 0) return [];

const when = (days) => (days === 0 ? "heute fällig" : days === 1 ? "morgen fällig" : `in ${days} Tagen fällig`);

return soon.map((item) => ({
  json: {
    source: "paperless",
    // Due today is worth a louder notification than due in three days, and
    // nothing here is ever critical: a deadline is not an outage.
    severity: item.days === 0 ? "warning" : "info",
    title: `${item.title} — ${when(item.days)}`,
    message: `Fällig am ${item.date}.`,
    // The document, its date and the rung of the ladder: the same document at
    // 3 days and at 0 days are different notifications, and neither should
    // suppress the other.
    fingerprint: `paperless:${item.id}:${item.date}:${item.days}`,
  },
}));
